def _adjudicate_review(self, issues: list[str], summary: str = "") -> dict[str, Any]:
    """Prüft nach dem letzten Review-Zyklus nur die noch beanstandeten Punkte erneut."""
    if self.reviewer_client is None:
        return {"verdict": "PASS", "summary": "Kein Reviewer für Schiedsrichter-Prüfung aktiv.", "issues": []}

    patch = workspace_patch_text(self.state.workspace, sorted(self.state.files_changed))
    if len(patch) > MAX_REVIEW_DIFF_CHARS:
        patch = truncate(patch, MAX_REVIEW_DIFF_CHARS)
    prompt = (
        "ORIGINALAUFTRAG:\n" + redact(self.state.task)
        + "\n\nLETZTE REVIEW-ZUSAMMENFASSUNG:\n" + redact(summary)
        + "\n\nBEANSTANDETE PUNKTE:\n- " + "\n- ".join(redact(x) for x in issues)
        + "\n\nAKTUELLER FINALER DIFF:\n" + redact(patch)
    )
    messages = [
        {"role": "system", "content": REVIEW_ADJUDICATION_SYSTEM_PROMPT},
        {"role": "user", "content": prompt},
    ]
    last_error = ""
    for _attempt in range(1, 3):
        raw = self.reviewer_client.complete(messages, max_tokens=REVIEW_ADJUDICATION_MAX_OUTPUT_TOKENS)
        try:
            parsed = self._extract_json(raw)
            verdict = str(parsed.get("verdict", "")).strip().upper()
            issues_raw = parsed.get("issues", [])
            checked_issues = (
                [shorten(redact(str(item)), 600) for item in issues_raw]
                if isinstance(issues_raw, list) else []
            )
            checked_summary = shorten(redact(str(parsed.get("summary", ""))), 1400)
            if verdict not in ("PASS", "FIX_REQUIRED"):
                raise AgentError("Review-Schiedsrichter verdict muss PASS oder FIX_REQUIRED sein.")
            if verdict == "FIX_REQUIRED" and not checked_issues:
                checked_issues = [checked_summary or "Schiedsrichter bestätigt Korrekturbedarf ohne Einzelpunkt."]
            return {"verdict": verdict, "summary": checked_summary, "issues": checked_issues}
        except Exception as exc:
            last_error = str(exc)
            messages.append({"role": "assistant", "content": raw[:2000]})
            messages.append({
